begin;
set local search_path=public,extensions;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temporary table search_ids(key text primary key,id uuid default gen_random_uuid());
grant all on search_ids to authenticated,service_role;
insert into search_ids(key) select unnest(array['a','b','owner','other_owner','organizer','inactive','outsider','org','other_org','club','other_club','tournament','claim']);
create function pg_temp.nid(k text) returns uuid language sql stable as $$select id from pg_temp.search_ids where key=k$$;
insert into auth.users(id,email) select id,'search-'||id||'@example.invalid' from search_ids where key in ('a','b','owner','other_owner','organizer','inactive','outsider');
insert into public.users(id,email,role) select id,'search-'||id||'@example.invalid',
  case when key in ('owner','other_owner') then 'CLUB'::public."ROLE" when key in ('organizer','inactive') then 'ORGANIZADOR'::public."ROLE" else 'PLAYER'::public."ROLE" end
  from search_ids where key in ('a','b','owner','other_owner','organizer','inactive','outsider');
insert into public.players(id,user_id,first_name,last_name,category_name) select id,id,key,'Search fixture','9na' from search_ids where key in ('a','b');
insert into public.organizaciones(id,name,slug) values(pg_temp.nid('org'),'Search fixture','search-'||pg_temp.nid('org'));
insert into public.organization_members(organizacion_id,user_id,is_active) values(pg_temp.nid('org'),pg_temp.nid('organizer'),true),(pg_temp.nid('org'),pg_temp.nid('inactive'),false);
insert into public.clubes(id,user_id,name) values(pg_temp.nid('club'),pg_temp.nid('owner'),'Search club'),(pg_temp.nid('other_club'),pg_temp.nid('other_owner'),'Other club');
insert into public.tournaments(id,club_id,organization_id,name,type,status,category_name,enable_public_inscriptions,is_draft,max_participants)
  values(pg_temp.nid('tournament'),pg_temp.nid('club'),pg_temp.nid('org'),'Search tournament','LONG','NOT_STARTED','9na',true,false,16);
insert into public.organizaciones(id,name,slug) values(pg_temp.nid('other_org'),'Other circuit','other-search-'||pg_temp.nid('other_org'));
insert into public.organization_members(organizacion_id,user_id,is_active) values(pg_temp.nid('other_org'),pg_temp.nid('other_owner'),true);
select ok(not has_function_privilege('authenticated','solo_player_private.notify_new_tournament_search()','EXECUTE'),'clients cannot invoke notification trigger');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.nid('a')::text,true);
insert into search_ids(key,id) select 'post',id from public.save_solo_player_post(pg_temp.nid('a'),'9na','DRIVE','RIGHT','+5491123456789',false,'solo-players-contact-v1',pg_temp.nid('tournament'),null,'solo-players-tournament-v1');
select is((select count(*) from public.solo_player_notifications),0::bigint,'player cannot read organizer notifications');
reset role;
select is((select count(*) from public.solo_player_notifications where post_id=pg_temp.nid('post')),2::bigint,'club owner and active organizer notified');
select is((select count(*) from public.solo_player_notifications where post_id=pg_temp.nid('post') and recipient_user_id in (pg_temp.nid('inactive'),pg_temp.nid('other_owner'),pg_temp.nid('a'))),0::bigint,'unrelated/inactive managers and author not notified');
select is((select count(*) from public.solo_player_notifications where post_id=pg_temp.nid('post') and request_id is null and event_type='PLAYER_SEARCHING' and email_status='PENDING'),2::bigint,'inbox and email queue created without a partner request');
select is((select count(*) from public.solo_player_requests where post_id=pg_temp.nid('post')),0::bigint,'no fabricated request');
insert into search_ids(key,id) select 'notification',id from public.solo_player_notifications where post_id=pg_temp.nid('post') and recipient_user_id=pg_temp.nid('owner');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.nid('a')::text,true);
select public.save_solo_player_post(pg_temp.nid('a'),'9na','REVES','LEFT','+5491123456789',false,'solo-players-contact-v1',pg_temp.nid('tournament'),null,'solo-players-tournament-v1',pg_temp.nid('post'));
select public.set_solo_player_post_status(pg_temp.nid('post'),'PAUSED');
select public.set_solo_player_post_status(pg_temp.nid('post'),'ACTIVE');
select set_config('request.jwt.claim.sub',pg_temp.nid('b')::text,true);
insert into search_ids(key,id) select 'general',id from public.save_solo_player_post_in_organization(pg_temp.nid('org'),pg_temp.nid('b'),'9na','DRIVE','RIGHT','+5491199999999',false,'solo-players-contact-v1',null,'1_DAY');
reset role;
select is((select count(*) from public.solo_player_notifications where post_id=pg_temp.nid('post')),2::bigint,'edit and pause/resume do not duplicate notifications');
select is((select count(*) from public.solo_player_notifications where post_id in (select id from public.solo_player_posts where player_id=pg_temp.nid('b'))),1::bigint,'general search notifies the active circuit organizer');
select is((select recipient_user_id from public.solo_player_notifications where post_id=pg_temp.nid('general')),pg_temp.nid('organizer'),'general search does not notify inactive or unrelated circuit managers');
select is((select email_status from public.solo_player_notifications where post_id=pg_temp.nid('general')),'PENDING','general search creates an email queue entry');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.nid('b')::text,true);
select public.set_solo_player_post_status(pg_temp.nid('general'),'PAUSED');
select public.save_solo_player_post_in_organization(pg_temp.nid('org'),pg_temp.nid('b'),'9na','REVES','LEFT','+5491199999999',false,'solo-players-contact-v1',null,'1_DAY',null,pg_temp.nid('general'));
select set_config('request.jwt.claim.sub',pg_temp.nid('organizer')::text,true);
select is((select count(*) from public.solo_player_posts where id=pg_temp.nid('general')),1::bigint,'recipient can open paused general search through RLS');
select is((select count(*) from public.solo_player_notifications where post_id=pg_temp.nid('general')),1::bigint,'editing general search does not duplicate its event');
select set_config('request.jwt.claim.sub',pg_temp.nid('outsider')::text,true);
select throws_ok($$select public.mark_solo_player_notification_read(pg_temp.nid('notification'))$$,'42501',null,'another account cannot mark organizer notification');
select set_config('request.jwt.claim.sub',pg_temp.nid('owner')::text,true);
select is((select count(*) from public.solo_player_notifications where post_id=pg_temp.nid('post')),1::bigint,'manager sees only their own notification');
select lives_ok($$select public.mark_solo_player_notification_read(pg_temp.nid('notification'))$$,'recipient can mark new event read');
reset role;
select ok((select read_at is not null from public.solo_player_notifications where id=pg_temp.nid('notification')),'read state persisted independently of email');
update public.solo_player_notifications set email_next_attempt_at=now()+interval '1 day' where post_id is distinct from pg_temp.nid('post');
set local role service_role;
select is((select count(*) from public.claim_solo_player_emails(pg_temp.nid('claim'),20)),2::bigint,'search emails use existing atomic delivery queue');
select ok(public.finish_solo_player_email(pg_temp.nid('notification'),pg_temp.nid('claim'),false,'PROVIDER_DOWN'),'failed email acknowledged for retry');
select is((select email_status from public.solo_player_notifications where id=pg_temp.nid('notification')),'FAILED','failed search email remains retryable');
select ok((select read_at is not null from public.solo_player_notifications where id=pg_temp.nid('notification')),'email failure preserves in-app event');
reset role;
select * from finish();
rollback;
